strong{font-weight:650}
'''
FONTS='<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400&family=IBM+Plex+Sans:wght@600;700&family=Source+Serif+4:opsz,wght@8..60,400;8..60,650&display=swap">'
for key,fn,title,who,desc,acc in docs:
    src=open(R+fn).read()
    m=re.match(r'<!--(.*?)-->\s*',src,re.S)
    about=m.group(1).strip() if m else ''
    body=src[m.end():] if m else src
    h=markdown.markdown(body,extensions=['sane_lists'])
    ab=markdown.markdown(about).replace('<p>','').replace('</p>','')
    navs=[]
    for k2,_,t2,w2,_,_ in docs:
        lab=w2
        if k2==key: navs.append(f'<span class="here">{html.escape(lab)}</span>')
        elif k2 in links: navs.append(f'<a href="{links[k2]}">{html.escape(lab)}</a>')
        else: navs.append(f'<span>{html.escape(lab)}</span>')
    page=f'''<title>{html.escape(title)}</title>
{FONTS}
<style>{CSS}:root{{--acc:var(--{acc})}}</style>
<main>
<nav aria-label="The three documents">{''.join(navs)}</nav>
<p class="eyebrow">Fortress revival · numerics on the path to compilation · {html.escape(who)}</p>
<p class="about">{ab}</p>
{h}
</main>
'''
    open(os.path.join(OUT,f'{key}.html'),'w').write(page)
    print(key,len(page))
EOF
